    { en: "bus driver", pos: "名", ja: "バスの運転手", ex: "The bus driver said hello to us.", exja: "バスの運転手さんがわたしたちにあいさつしてくれた。" },
    { en: "lobby", pos: "名", ja: "ロビー", ex: "Let's meet in the hotel lobby at nine.", exja: "9時にホテルのロビーで会いましょう。" },
    { en: "clothing store", pos: "名", ja: "洋服屋", ex: "I bought a jacket at the clothing store.", exja: "わたしはその洋服屋でジャケットを買った。" },
    { en: "video camera", pos: "名", ja: "ビデオカメラ", ex: "My father used a video camera at my sports day.", exja: "父はわたしの運動会でビデオカメラを使った。" },
    { en: "crayon", pos: "名", ja: "クレヨン", ex: "The children drew pictures with crayons.", exja: "子どもたちはクレヨンで絵をかいた。" },
    { en: "quiz show", pos: "名", ja: "クイズ番組", ex: "My family watches a quiz show every Friday.", exja: "わたしの家族は毎週金曜日にクイズ番組を見る。" },
    { en: "zookeeper", pos: "名", ja: "動物園の飼育員", ex: "The zookeeper gave food to the elephants.", exja: "飼育員さんがゾウにえさをあげた。" },
    { en: "twin room", pos: "名", ja: "ツインルーム", ex: "We stayed in a twin room at the hotel.", exja: "わたしたちはホテルのツインルームにとまった。" },
    { en: "tempura", pos: "名", ja: "天ぷら", ex: "My grandmother made shrimp tempura for us.", exja: "祖母がわたしたちにエビの天ぷらを作ってくれた。" },
    { en: "hot chocolate", pos: "名", ja: "ココア", ex: "I drink hot chocolate on cold days.", exja: "寒い日には、わたしはココアを飲む。" },
    { en: "fried rice", pos: "名", ja: "チャーハン", ex: "My father makes very good fried rice.", exja: "父はとてもおいしいチャーハンを作る。" },
    { en: "grapefruit", pos: "名", ja: "グレープフルーツ", ex: "I eat half a grapefruit every morning.", exja: "わたしは毎朝グレープフルーツを半分食べる。" },
    { en: "sweet potato", pos: "名", ja: "サツマイモ", ex: "We ate baked sweet potatoes in the park.", exja: "わたしたちは公園で焼きいもを食べた。" },
    { en: "pine tree", pos: "名", ja: "松の木", ex: "There is an old pine tree in the garden.", exja: "庭に古い松の木がある。" },
    { en: "hamster", pos: "名", ja: "ハムスター", ex: "My hamster runs on its wheel at night.", exja: "うちのハムスターは夜に回し車で走る。" },
    { en: "owl", pos: "名", ja: "フクロウ", ex: "We heard an owl in the forest at night.", exja: "夜、森でフクロウの鳴き声が聞こえた。" },
    { en: "jellyfish", pos: "名", ja: "クラゲ", ex: "Be careful of jellyfish in the sea.", exja: "海ではクラゲに気をつけて。" },
    { en: "polar bear", pos: "名", ja: "ホッキョクグマ", ex: "Polar bears live in very cold places.", exja: "ホッキョクグマはとても寒い所にすんでいる。" },
    { en: "firefly", pos: "名", ja: "ホタル", ex: "We saw many fireflies near the river.", exja: "わたしたちは川の近くでたくさんのホタルを見た。" },
    { en: "world-famous", pos: "形", ja: "世界的に有名な", ex: "Many people visit this world-famous temple in Kyoto.", exja: "多くの人が、京都のこの世界的に有名なお寺をおとずれる。" }
