    "cream": { hint: "ショートケーキのいちごの下にある、白くてふわふわ", core: "牛乳の中の『あぶらの多い部分』。ケーキやコーヒーに使う。はだにぬるものも。", tip: "ice cream＝アイスクリーム。『ハンドクリーム』も同じ語。", pic: "🍰", scene: "ボウルの白い液をあわ立て器でかきまぜると、角が立つほどふわふわに。", flow: ["牛乳のあぶらの部分", "クリーム", "ぬるクリーム"] },
    "flute": { hint: "ブラスバンドで、横にかまえて息をふきこむ銀色の楽器", core: "横にして、あなに息をふきこんで音を出す『笛』。", tip: "play the flute と the をつける。", pic: "🎶", scene: "音楽室で、口に当てた銀色の楽器から、鳥の声のようなきれいな音が流れる。", flow: ["横にかまえる笛", "フルート"] },
    "solo": { hint: "コンサートで、ほかの音が止まり、一人だけにライトが当たる", core: "イタリア語で『ひとりの』。一人だけで歌ったり、えんそうしたりすること。", tip: "『ソロ活動』『ソロキャンプ』のソロ。", pic: "🎤", scene: "合唱の中で一人だけ前に出て、体育館じゅうにすんだ歌声をひびかせる。", flow: ["ひとりの", "一人での歌・えんそう", "ソロ"] },
    "riddle": { hint: "「パンはパンでも、食べられないパンはなーんだ？」", core: "答えをかくして、ことばで『考えさせる』問題。", tip: "read（読む）と同じ仲間で、もとは『読みとく・あてる』から。", pic: "🤔", scene: "車の中で、弟が「上は大水、下は大火事、なーんだ？」と言い、みんなで首をひねる。", flow: ["考えさせる問題", "なぞなぞ", "なぞ"] },
    "marathon": { hint: "42.195キロ、とても長いきょりを走る競技", core: "ギリシャのマラトンという町から走った、むかしの話からついた名前。", tip: "マラトンからアテネまで、勝ったことを伝えに走った話から。", pic: "🏃", scene: "旗をふる人たちの中、ゴール前の選手が最後の力をしぼって走る。", flow: ["マラトンの話", "長いきょり走", "マラソン"] },
    "judo": { hint: "白い服に黒い帯。たたみの上で相手を投げる", core: "日本で生まれた武道。日本語がそのまま英語になった。", tip: "practice judo / do judo。karate（空手）も英語になった。", pic: "🥋", scene: "道場で、白い道着の二人がえりをつかみ合い、えいっと相手を投げる。", flow: ["日本の武道", "柔道"] },
    "boxing": { hint: "大きなグローブをつけて、リングの上で打ち合う", core: "box（こぶしで打つ）＋ing。グローブでパンチし合うスポーツ。", tip: "box には『箱』のほかに『こぶしで打つ』という意味もある。", pic: "🥊", scene: "ゴングが鳴ると、リングの上の二人がグローブをかまえ、すばやく動き出す。", flow: ["こぶしで打つ", "ボクシング"], parts: [["box", "こぶしで打つ"], ["ing", "～すること"]] },
    "ribbon": { hint: "プレゼントの箱に、ちょうちょ結びでかざる", core: "かざりに使う、細長い『布のひも』。", tip: "カタカナの『リボン』。tie a ribbon＝リボンを結ぶ。", pic: "🎀", scene: "妹のかみに赤い布をちょうちょ結びにすると、鏡を見てにっこり。", flow: ["細長い布", "リボン"] },
    "carnival": { hint: "ブラジルの町で、はでな衣しょうの人がサンバをおどりパレード", core: "大ぜいがパレードやおどりで楽しむ、にぎやかな『お祭り』。", tip: "もとは、肉を食べない期間の前に楽しんだお祭り。", pic: "🎭", scene: "夜の大通りを、羽根をつけた人たちが音楽に合わせて何時間もおどり歩く。", flow: ["にぎやかなお祭り", "カーニバル"] },
    "drugstore": { hint: "かぜ薬も、シャンプーも、おかしも売っている店", core: "drug（薬）＋store（店）。薬のほか、毎日使う物も売っている店。", tip: "drug は『薬』。store は『店』。", pic: "💊", scene: "白い服の店の人に、「せきの薬はどれですか」とたずねる。", flow: ["薬の店", "ドラッグストア・薬局"], parts: [["drug", "薬"], ["store", "店"]] },
    "police": { hint: "どろぼうを見たら110番に電話。パトカーでかけつける", core: "町の安全を守る『組織』。そこで働く人は police officer。", tip: "police station＝警察署、police officer＝警察官。", pic: "🚓", scene: "サイレンを鳴らしてパトカーが止まり、制服の人がおりてくる。", flow: ["町を守る組織", "警察", "police officer＝警察官"] },
    "waiter": { hint: "レストランで料理を運び、「ご注文は？」と聞く男の人", core: "wait（待つ・仕える）＋er（人）。お客のそばでひかえて、料理を運ぶ人。", tip: "女の人は waitress。wait on ～＝～のお世話をする。", pic: "🍽️", scene: "白いエプロンの人が、両手に料理の皿を持ってテーブルへやってくる。", flow: ["そばでひかえる人", "給仕", "ウェイター"], parts: [["wait", "待つ・仕える"], ["er", "～する人"]] },
    "flight attendant": { hint: "空港でスーツケースを引き、制服で飛行機へ向かう人たち", core: "flight（飛行）＋attendant（世話をする人）。飛行機でお客のお世話をする人。", tip: "attend（出席する・世話をする）の仲間。", pic: "✈️", scene: "飛行機の通路をワゴンでまわり、「お飲み物はいかがですか」と笑顔で聞く。", flow: ["飛行機で世話をする人", "客室乗務員"], parts: [["flight", "飛行"], ["attendant", "世話をする人"]] },
    "wrist": { hint: "うで時計をまく所。テニスでいためやすい", core: "手とうでをつなぐ、『くるっと曲がる』ところ。", tip: "wristwatch＝うで時計。wristband＝リストバンド。", pic: "⌚", scene: "バドミントンで、そこをくいっと返して、強いスマッシュを打つ。", flow: ["手とうでのつなぎめ", "手首"] },
    "action": { hint: "「見ているだけじゃなく、すぐやろう！」と言うとき", core: "act（行う）＋ion（こと）。じっさいに体を動かしてすること。", tip: "『アクション映画』＝動きがはげしい映画。act＝行う。", pic: "🏃‍♂️", scene: "ごみを見つけて、文句を言うより先に、しゃがんで自分で拾う。", flow: ["じっさいにすること", "行動", "動き・アクション"], parts: [["act", "行う"], ["ion", "～こと"]], fam: ["act（行う）", "active（活発な）"] },
