    "turkey": { hint: "アメリカの感謝祭に、丸焼きで出てくる大きな鳥", core: "大きな鳥。アメリカでは感謝祭に丸焼きにして食べる。", tip: "大文字の Turkey は国の『トルコ』。", pic: "🦃", scene: "テーブルのまん中に、こんがり焼けた大きな鳥がどんとおかれる。", flow: ["大きな鳥", "七面鳥", "その肉"] },
    "alarm clock": { hint: "朝6時、ジリリリ！とまくらもとで鳴りひびく", core: "alarm（知らせる音）＋clock（時計）。決めた時間に鳴って起こしてくれる時計。", tip: "alarm は『アラーム』。fire alarm＝火災報知器。", pic: "⏰", scene: "ねぼけた手で頭の上をたたいて、鳴りつづける音を止める。", flow: ["音で知らせる時計", "目覚まし時計"], parts: [["alarm", "知らせる音"], ["clock", "時計"]] },
    "beginning": { hint: "物語の第1ページ。運動会なら開会式", core: "begin（始まる）＋ing。何かが始まるところ。", tip: "n を2つ重ねる。at the beginning of ～（～の初めに）。", pic: "🏁", scene: "映画が始まり、まっ暗な画面に小さな光が1つともる。", flow: ["始まるところ", "初め・最初"], parts: [["begin", "始まる"], ["ing", "～こと"]] },
