    "climbing": { hint: "リュックをせおって、つえをついて、てっぺんを目ざす", core: "climb（よじ登る）＋ing。手足を使って山やかべを登ること。", tip: "b は読まない［クライミング］。rock climbing＝岩登り。", pic: "🧗", scene: "岩のかべで、手と足をかける所をさがし、少しずつ上へ進む。", flow: ["よじ登ること", "山登り", "クライミング"], parts: [["climb", "よじ登る"], ["ing", "～こと"]] },
    "death": { hint: "長生きしたペットが、ある朝もう動かなくなっていた", core: "die（死ぬ）の名詞の形。命がおわること。", tip: "die（死ぬ）→dead（死んでいる）→death（死）。3つセットで。", pic: "🥀", scene: "古い木の下に小さなお墓をつくり、みんなで花をそなえる。", flow: ["命がおわること", "死"], fam: ["die（死ぬ）", "dead（死んだ）"] },
    "education": { hint: "国が学校をつくり、子どもたちが読み書きを学べるようにする", core: "その人の中にある力を『外へみちびき出して』育てること。", tip: "e（外へ）＋duc（みちびく）。produce（生産する）と同じ duc。", pic: "🏫", scene: "先生が黒板の前で、子どもたちの手が次々に上がるのを見てうなずく。", flow: ["力をみちびき出す", "教育"], parts: [["e", "外へ"], ["duc", "みちびく"], ["ation", "～こと"]] },
    "first name": { hint: "「サトウ・ハナ」のうち、友だちがよぶほう", core: "英語では名前を先に（first）言うので first name。家の名前は last name。", tip: "family name / last name＝名字。", pic: "📛", scene: "外国の先生が「Call me Tom.」と、名字でなく、もう一つの名前でよんでと言う。", flow: ["最初に言う名前", "下の名前"], parts: [["first", "最初の"], ["name", "名前"]] },
    "grandson": { hint: "おばあちゃんが、お正月にお年玉をあげる小さなぼうや", core: "grand（一代はなれた）＋son（むすこ）。子どもの子どもで、男の子。", tip: "女の子は granddaughter。grandfather の grand と同じ。", pic: "👴👦", scene: "おじいちゃんのひざの上で、小さな男の子が昔話を聞いている。", flow: ["子どもの子ども", "男の孫"], parts: [["grand", "一代はなれた"], ["son", "むすこ"]], fam: ["granddaughter（孫むすめ）", "grandfather（祖父）"] },
    "midnight": { hint: "時計の長い針も短い針も、てっぺんの12", core: "mid（まん中）＋night（夜）。夜のまん中＝夜の12時。", tip: "mid はミドル（middle）の仲間。midnight snack＝夜食。", pic: "🌙🕛", scene: "大みそか、時計が12時を打つと、遠くでかねの音がひびく。", flow: ["夜のまん中", "夜中の12時", "真夜中"], parts: [["mid", "まん中"], ["night", "夜"]] },
