    "puppy": { hint: "生まれて2か月。ころころ走って、くつをかんでしまう", core: "まだ小さい『犬の子ども』。", tip: "子ネコは kitten。", pic: "🐶", scene: "段ボールの中で、ふわふわの3びきが、しっぽをふってクンクン鳴く。", flow: ["犬の子ども", "子犬"] },
